from collections import Counter
import re

class NLPDataProcessor2:

    TOP_N = 5

    def process_data(self, string_list):
        return self._extract_words_per_string(string_list)

    def _extract_words_per_string(self, string_list):
        words_list = []
        for string in string_list:
            words_list.append(self._process_single_string(string))
        return words_list

    def _process_single_string(self, string):
        cleaned = self._remove_non_english_letters(string)
        return cleaned.split()

    def _remove_non_english_letters(self, string):
        return re.sub(r'[^a-zA-Z\s]', '', string.lower())

    def calculate_word_frequency(self, words_list, top_n=None):
        if top_n is None:
            top_n = self.TOP_N
        word_counter = self._count_words(words_list)
        return self._get_top_n_words(word_counter, top_n)

    def _count_words(self, words_list):
        counter = Counter()
        for words in words_list:
            counter.update(words)
        return counter

    def _get_top_n_words(self, counter, n):
        sorted_items = sorted(counter.items(), key=lambda x: x[1], reverse=True)
        return dict(sorted_items[:n])

    def process(self, string_list, top_n=None):
        words_list = self.process_data(string_list)
        return self.calculate_word_frequency(words_list, top_n)
